import {formatAstral,ASTRAL_NOTATION_HELP} from './astral.js';
export function paintAstral(economy){const put=(id,text)=>{const el=document.getElementById(id);if(el)el.textContent=text;};const power=document.getElementById('astral-power');if(power)power.title=ASTRAL_NOTATION_HELP;put('astral-wallet',formatAstral(economy.currency));put('astral-rate','+'+formatAstral(economy.rate)+' / sec');put('astral-power','×'+formatAstral(economy.power));for(const id of ['generator','exponent','tower']){const offer=economy.offer(id),button=document.getElementById('astral-buy-'+id);if(!button)continue;button.disabled=!offer.canBuy;put('astral-name-'+id,offer.name+' Lv.'+offer.level);put('astral-effect-'+id,offer.legacyLevel?offer.effect+' · 引継 Lv.'+offer.legacyLevel:offer.effect);put('astral-cost-'+id,offer.maxed?(offer.capText||'MAX'):offer.locked?offer.unlockText:offer.readyIn>0?`充填 ${offer.readyIn.toFixed(1)}s`:'必要 '+formatAstral(offer.cost));put('astral-next-'+id,'NEXT ×'+formatAstral(offer.nextPower));}}
